const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: `Bearer ${SK}` };
const {execSync} = require('child_process');

const since = new Date(Date.now() - 7*24*60*60*1000).toISOString();

const doneRes = await fetch(`${SUPA}/rest/v1/issues?status=in.(completed,closed,released)&updated_at=gte.${since}&select=task_key,title,project,resolution_type,status`, {headers:h});
const done = await doneRes.json();

const activeRes = await fetch(`${SUPA}/rest/v1/issues?status=in.(open,in_progress,code_review,product_review,approved,released,completed)&select=project,priority,status`, {headers:h});
const active = await activeRes.json();
const byProject = {};
active.forEach(i => byProject[i.project] = (byProject[i.project]||0)+1);

const critRes = await fetch(`${SUPA}/rest/v1/issues?priority=eq.critical&status=in.(open,in_progress,code_review,product_review,approved,released,completed)&select=task_key,title,project,assignee,status&limit=5`, {headers:h});
const crits = await critRes.json();

const shipped = done.slice(0,10).map(i=>`• [${i.task_key}] ${i.project}: ${i.title.slice(0,50)} (${i.status})`).join('\n');
const activeSummary = Object.entries(byProject).map(([p,n])=>`• ${p}: ${n} active`).join('\n');
const critSummary = crits.length ? crits.map(i=>`• [${i.task_key}] ${i.title.slice(0,50)} → ${i.assignee||'unassigned'} (${i.status})`).join('\n') : '• None 🎉';

const brief = [
  '📊 **Weekly Executive Brief** — ' + new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}),
  '',
  `**Shipped / sign-off this week:** ${done.length} issues`,
  shipped || '• (none)',
  '',
  '**Active pipeline by project:**',
  activeSummary || '• (all clear)',
  '',
  '**Critical issues in flight:**',
  critSummary,
  '',
  '**This week focus:** Review #pr-reviews for pending merges. Check Growth report in #growth-reports.'
].join('\n');

const esc = brief.replace(/'/g, "'\\''" );
try { execSync(`openclaw message send --channel telegram --target 5084875115 --message '${esc}' 2>/dev/null || true`); } catch(e) {}
try { execSync(`openclaw message send --channel discord --target "channel:14878220390029067744" --message '${esc}' 2>/dev/null || true`); } catch(e) {}

return [{json:{action:'brief_sent', shipped: done.length, active: active.length}}];
